import { useState, useRef, useCallback, useEffect } from 'react';

const API = 'http://localhost:5050';

/* ─── DESIGN TOKENS ─────────────────────────────────────────────── */
const C = {
  bg:      '#07080d',
  bg2:     '#0e0f18',
  bg3:     '#141520',
  card:    '#191b28',
  border:  'rgba(255,255,255,0.07)',
  border2: 'rgba(255,255,255,0.13)',
  text:    '#f0f2ff',
  muted:   '#6b7094',
  muted2:  '#3a3d58',
  m1:      '#818cf8',
  m2:      '#fb923c',
  m3:      '#34d399',
  danger:  '#f87171',
  warn:    '#fbbf24',
};

const f = {
  display: "'Outfit', sans-serif",
  mono:    "'JetBrains Mono', monospace",
};

/* ─── GLOBAL STYLES injected once ───────────────────────────────── */
const GlobalStyle = () => {
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
      html { scroll-behavior: smooth; }
      body {
        background: ${C.bg};
        color: ${C.text};
        font-family: ${f.display};
        min-height: 100vh;
        overflow-x: hidden;
        -webkit-font-smoothing: antialiased;
      }
      body::before {
        content: '';
        position: fixed; inset: 0; pointer-events: none; z-index: 0;
        background:
          radial-gradient(ellipse 80% 50% at 20% 10%, rgba(129,140,248,0.06) 0%, transparent 60%),
          radial-gradient(ellipse 60% 40% at 80% 90%, rgba(52,211,153,0.04) 0%, transparent 60%);
      }
      ::-webkit-scrollbar { width: 5px; }
      ::-webkit-scrollbar-track { background: ${C.bg}; }
      ::-webkit-scrollbar-thumb { background: ${C.muted2}; border-radius: 3px; }
      @keyframes spin { to { transform: rotate(360deg); } }
      @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.3} }
      @keyframes slideUp {
        from { opacity: 0; transform: translateY(24px); }
        to   { opacity: 1; transform: translateY(0); }
      }
      @keyframes shimmer {
        0%   { background-position: -400px 0; }
        100% { background-position: 400px 0; }
      }
      .slide-up { animation: slideUp 0.45s cubic-bezier(0.16,1,0.3,1) both; }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);
  return null;
};

